import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        long w = scanner.nextLong();
        long m = scanner.nextLong();

        long[] sum = new long[105];
        long[] pw = new long[105];
        boolean[] possible = {false};

        long p = 1;
        int maxIndex = 0;
        for (int i = 0; i < 100; i++) {
            sum[i + 1] = sum[i] + p;
            pw[i] = p;
            p *= w;
            if (p > (1L << 40)) {
                maxIndex = i;
                break;
            }
        }

        verify(0, m, maxIndex, sum, pw, possible);
        System.out.println(possible[0] ? "YES" : "NO");
    }

    static void verify(long current, long target, int index, long[] sum, long[] pw, boolean[] possible) {
        if (possible[0]) return;
        if (current == target) {
            possible[0] = true;
            return;
        }
        long remainingSum = sum[index + 1];
        long powerVal = pw[index];

        if (current - remainingSum > target || current + remainingSum < target) {
            return;
        }

        if (current + sum[index] < target) {
            verify(current + powerVal, target, index - 1, sum, pw, possible);
        } else if (current - sum[index] > target) {
            verify(current - powerVal, target, index - 1, sum, pw, possible);
        } else {
            verify(current, target, index - 1, sum, pw, possible);
        }
    }
}
